weltallRecoveredLaunch = getIntent().getBooleanExtra("weltallRecoveredActivity", false);
if (weltallRecoveredLaunch) {
    android.widget.Toast.makeText(this, "Game restarted. Load a saved game to continue.", android.widget.Toast.LENGTH_LONG).show();
    getIntent().removeExtra("weltallRecoveredActivity");
}

